mapper.select:
SELECT d.id, d.order_id, d.reason_type, d.statement, d.evidence AS evidence_json, d.status, d.created_at, o.order_no, o.status AS order_status, p.title AS product_title, buyer.nickname AS buyer_name, seller.nickname AS seller_name FROM dispute d LEFT JOIN trade_order o ON o.id = d.order_id LEFT JOIN product p ON p.id = o.product_id LEFT JOIN `user` buyer ON buyer.id = o.buyer_id LEFT JOIN `user` seller ON seller.id = o.seller_id
d.status = #{status}
AND ( d.created_at < #{cursorCreatedAt} OR (d.created_at = #{cursorCreatedAt} AND d.id < #{cursorId}) )
ORDER BY d.created_at DESC, d.id DESC LIMIT #{limit}
